<?php
namespace App\Domain\Workplan\Services;
use App\Domain\Workplan\Models\{WorkplanEvidence,WorkplanProgressReport}; use App\Enums\WorkplanProgressStatus; use App\Models\User; use App\Services\AuditLogService; use Illuminate\Http\UploadedFile; use Illuminate\Support\Facades\Storage; use Illuminate\Validation\ValidationException;
class WorkplanEvidenceService { public function __construct(private AuditLogService $audit){} public function store(WorkplanProgressReport $r,array $data,User $u):WorkplanEvidence{$this->access($r,$u);$this->editable($r);$file=$data['file']??null;$path=null;if(($data['evidence_type']??'')==='file'){$path=$file->store("workplans/{$r->mda_id}/{$r->workplan_id}/activities/{$r->workplan_activity_id}/progress/{$r->id}/evidence",'local');}$e=$r->evidence()->create(['mda_id'=>$r->mda_id,'workplan_id'=>$r->workplan_id,'workplan_activity_id'=>$r->workplan_activity_id,'title'=>$data['title'],'evidence_type'=>$data['evidence_type'],'file_path'=>$path,'file_mime_type'=>$file?->getMimeType(),'file_size'=>$file?->getSize(),'external_url'=>$data['external_url']??null,'notes'=>$data['notes']??null,'uploaded_by'=>$u->id]);$this->audit->log($e->evidence_type==='link'?'workplan.evidence.linked':'workplan.evidence.uploaded',$e,[],$e->toArray(),['mda_id'=>$r->mda_id,'workplan_id'=>$r->workplan_id,'activity_id'=>$r->workplan_activity_id,'progress_report_id'=>$r->id]);return $e->fresh('uploadedBy');} public function delete(WorkplanEvidence $e,User $u):void{$r=WorkplanProgressReport::withoutGlobalScopes()->findOrFail($e->workplan_progress_report_id);abort_unless((int)$r->mda_id===(int)$e->mda_id,404);$this->access($r,$u);$this->editable($r);$before=$e->toArray();if($e->file_path)Storage::disk('local')->delete($e->file_path);$e->delete();$this->audit->log('workplan.evidence.deleted',WorkplanEvidence::class,$before,[],['mda_id'=>$r->mda_id,'progress_report_id'=>$r->id]);} private function access(WorkplanProgressReport $r,User $u):void{abort_unless($u->can('update-workplan-progress')&&$u->canAccessMda($r->mda_id)&&($r->activity->department_id===null||$u->canAccessDepartment($r->activity->department_id)),403);} private function editable(WorkplanProgressReport $r):void{if(!in_array($r->status,[WorkplanProgressStatus::DRAFT,WorkplanProgressStatus::RETURNED],true))throw ValidationException::withMessages(['evidence'=>'Evidence is locked after submission.']);}}
